-- Virtual-account ordering scenarios split from
-- manual_order_documents_dispatch.sql (300-line gate). Runs immediately
-- after it in the same psql session: the tie cases reuse order 017 and
-- its selected 9990002222 virtual account, left in place by the dispatch
-- suite, and the twin 9990001111 row stays behind like before the split.
--
-- A blank canonical address field falls back to the legacy alias before
-- the blank collapses: the builders render `address_line1 || address`,
-- so the canonicalizer must resolve the alias instead of selecting the
-- empty canonical value and discarding it.
SELECT pg_temp.assert_true((SELECT private.rendered_shipping_address('{"address_line1": "", "address": "Alias St", "postal_code": "", "postalCode": "100001"}'::jsonb) = private.rendered_shipping_address('{"address_line1": "Alias St", "postal_code": "100001"}'::jsonb)), 'blank canonical falls back to legacy aliases');

-- Same-transaction virtual accounts tie on created_at: the account-number
-- tie-break picks the same row on every recheck.
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
INSERT INTO public.order_payment_accounts (order_id, account_number, bank_name, account_name, provider, expires_at, created_at) VALUES ('10000000-0000-4000-8000-000000000017', '9990001111', 'Paystack-Titan', 'Shop Ltd/ORD17-twin', 'paystack', NULL, (SELECT created_at FROM public.order_payment_accounts WHERE order_id = '10000000-0000-4000-8000-000000000017' AND account_number = '9990002222'));
-- Rearm stole the claim; the retry worker re-claims before the mark.
UPDATE public.order_notification_outbox SET status = 'processing', locked_by = 'm2-worker', locked_at = now() WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', NULL, NULL, 100, 0, 0, 0, 0, 50, 'NGN', NULL, 'partially_paid', 'invoice', 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'proforma_invoice', 1, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000017'), '058', '1234567890', 'GTBank', 'Shop Ltd', '9990002222', 'Paystack-Titan', 'Shop Ltd/ORD17', 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T10:00:00Z')->>'status' = 'marked'), 'tied virtual accounts resolve deterministically');
-- A future-assigned newest account is invisible to the sender's selector: the recheck skips it and matches the older eligible row instead of staling every attempt.
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
INSERT INTO public.order_payment_accounts (order_id, account_number, bank_name, account_name, provider, expires_at, created_at, assigned_at) VALUES ('10000000-0000-4000-8000-000000000017', '9990003333', 'Paystack-Titan', 'Shop Ltd/ORD17-future', 'paystack', NULL, now() + interval '1 hour', now() + interval '1 hour');
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', NULL, NULL, 100, 0, 0, 0, 0, 50, 'NGN', NULL, 'partially_paid', 'invoice', 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'proforma_invoice', 1, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000017'), '058', '1234567890', 'GTBank', 'Shop Ltd', '9990002222', 'Paystack-Titan', 'Shop Ltd/ORD17', 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T10:00:00Z')->>'status' = 'marked'), 'future-assigned newest account falls back to the older eligible row');
DELETE FROM public.order_payment_accounts WHERE order_id = '10000000-0000-4000-8000-000000000017' AND account_number = '9990003333';
-- Paystack ranks above a newer non-Paystack row like the shared selector:
-- only Paystack DVA rows match the webhook, so the recheck still matches
-- the older eligible Paystack row instead of the newest Korapay one.
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
INSERT INTO public.order_payment_accounts (order_id, account_number, bank_name, account_name, provider, expires_at, created_at) VALUES ('10000000-0000-4000-8000-000000000017', '5550002222', 'Korapay', 'Shop Ltd/ORD17K2', 'korapay', NULL, now());
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', NULL, NULL, 100, 0, 0, 0, 0, 50, 'NGN', NULL, 'partially_paid', 'invoice', 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'proforma_invoice', 1, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000017'), '058', '1234567890', 'GTBank', 'Shop Ltd', '9990002222', 'Paystack-Titan', 'Shop Ltd/ORD17', 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T10:00:00Z')->>'status' = 'marked'), 'newer Korapay assignment loses to the eligible Paystack row');
DELETE FROM public.order_payment_accounts WHERE order_id = '10000000-0000-4000-8000-000000000017' AND account_number = '5550002222';

-- A null-created legacy account never beats a dated one: the recheck sorts
-- nulls last like the sender and the shared selector.
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
INSERT INTO public.order_payment_accounts (order_id, account_number, bank_name, account_name, provider, expires_at, created_at) VALUES ('10000000-0000-4000-8000-000000000017', '9990009999', 'Paystack-Titan', 'Shop Ltd/ORD17-legacy', 'paystack', NULL, NULL);
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', NULL, NULL, 100, 0, 0, 0, 0, 50, 'NGN', NULL, 'partially_paid', 'invoice', 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'proforma_invoice', 1, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000017'), '058', '1234567890', 'GTBank', 'Shop Ltd', '9990002222', 'Paystack-Titan', 'Shop Ltd/ORD17', 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T10:00:00Z')->>'status' = 'marked'), 'null-created legacy account loses to the dated row');
DELETE FROM public.order_payment_accounts WHERE order_id = '10000000-0000-4000-8000-000000000017' AND account_number = '9990009999';
